ALTER TABLE dbo.attachments ADD CONSTRAINT CK_attachments_invalidation CHECK ((invalidated_at IS NULL AND invalidation_reason IS NULL) OR (invalidated_at IS NOT NULL AND invalidation_reason IS NOT NULL));
ALTER TABLE dbo.audit_logs ADD CONSTRAINT CK_audit_logs_before_json CHECK (before_json IS NULL OR ISJSON(before_json)=1);
ALTER TABLE dbo.audit_logs ADD CONSTRAINT CK_audit_logs_after_json CHECK (after_json IS NULL OR ISJSON(after_json)=1);
ALTER TABLE dbo.notifications ADD CONSTRAINT CK_notifications_attempts CHECK (attempt_count>=0);
ALTER TABLE dbo.notifications ADD CONSTRAINT CK_notifications_lease CHECK ((lease_id IS NULL AND lease_until IS NULL) OR (lease_id IS NOT NULL AND lease_until IS NOT NULL));
ALTER TABLE dbo.notifications ADD CONSTRAINT CK_notifications_ack CHECK (acknowledged_at IS NULL OR (requires_acknowledgment=1 AND delivered_at IS NOT NULL AND acknowledged_at>=delivered_at));
GO
EXEC sys.sp_addextendedproperty @name=N'HotelOpsCompactSchema',@value=N'1.0.0';
